// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import java.util.ArrayList;
import java.util.List;

import org.junit.jupiter.api.Test;

/**
 * A tiered range merge replaces a few generations by one merged generation holding the newest version of every key in
 * that range. The overlay set's latest-row index must then be remapped in proportion to the merged and later rows, not
 * rebuilt over every row: the rebuild ran on the single applier thread after every merge and made small commits wait
 * for a time that grew with the rows since the last fold.
 */
class LmdbAdjacencyOverlaySetReplaceRangeTest {

	private static final int PLANE = 0;
	private static final long PREDICATE = 7L;

	@Test
	void replacingTheNewestRangeKeepsLookupsExactAndSharesTheUntouchedTree() {
		int count = 600;
		LmdbAdjacencyDeltaGeneration[] generations = new LmdbAdjacencyDeltaGeneration[count];
		for (int i = 0; i < count; i++) {
			generations[i] = generation(i + 1, new long[] { key(i) });
		}
		LmdbAdjacencyOverlaySet before = overlays(generations);
		int from = count - 4;
		int toInclusive = count - 1;
		LmdbAdjacencyDeltaGeneration merged = generation(count,
				new long[] { key(from), key(from + 1), key(from + 2), key(from + 3) });

		LmdbAdjacencyOverlaySet after = before.withReplacedRange(replacement(generations, from, toInclusive, merged),
				from, toInclusive, before.contextCatalog(), new long[0], 0L, null);

		assertThat(after.generationCount()).isEqualTo(count - 3);
		assertThat(after.generation(from)).isSameAs(merged);
		assertThat(after.latestRowCount()).isEqualTo(count);
		LmdbAdjacencyOverlaySet.LatestRowLookup lookup = new LmdbAdjacencyOverlaySet.LatestRowLookup();
		for (int i = 0; i < from; i++) {
			assertThat(after.findLatest(key(i), PLANE, PREDICATE, lookup)).isTrue();
			assertThat(lookup.generation()).isSameAs(generations[i]);
			assertThat(lookup.generationIndex()).isEqualTo(i);
			assertThat(lookup.rowIndex()).isZero();
		}
		for (int i = from; i <= toInclusive; i++) {
			assertThat(after.findLatest(key(i), PLANE, PREDICATE, lookup)).isTrue();
			assertThat(lookup.generation()).isSameAs(merged);
			assertThat(lookup.generationIndex()).isEqualTo(from);
			assertThat(lookup.rowIndex()).isEqualTo(i - from);
		}
		assertIndicesConsistent(after);
		assertThat(after.latestRowNodesSharedWithForTest(before))
				.as("remapping four rows of a %d-row index rewrites only their search paths", count)
				.isGreaterThan(count - 4 * 12);
	}

	@Test
	void replacingAnOlderRangeRenumbersTheRowsOfLaterGenerations() {
		int count = 40;
		LmdbAdjacencyDeltaGeneration[] generations = new LmdbAdjacencyDeltaGeneration[count];
		for (int i = 0; i < count; i++) {
			generations[i] = generation(i + 1, new long[] { key(i), key(1000 + i % 3) });
		}
		LmdbAdjacencyOverlaySet before = overlays(generations);
		int from = 8;
		int toInclusive = 15;
		// the newest version of every key in [8, 15]: eight distinct keys plus the three shared keys
		LmdbAdjacencyDeltaGeneration merged = generation(toInclusive + 1, new long[] { key(8), key(9), key(10),
				key(11), key(12), key(13), key(14), key(15), key(1000), key(1001), key(1002) });

		LmdbAdjacencyOverlaySet after = before.withReplacedRange(replacement(generations, from, toInclusive, merged),
				from, toInclusive, before.contextCatalog(), new long[0], 0L, null);

		assertThat(after.generationCount()).isEqualTo(count - 7);
		LmdbAdjacencyOverlaySet.LatestRowLookup lookup = new LmdbAdjacencyOverlaySet.LatestRowLookup();
		for (int i = toInclusive + 1; i < count; i++) {
			assertThat(after.findLatest(key(i), PLANE, PREDICATE, lookup)).isTrue();
			assertThat(lookup.generation()).isSameAs(generations[i]);
			assertThat(lookup.generationIndex()).as("generation %d shifts down by the removed count", i)
					.isEqualTo(i - 7);
		}
		for (int shared = 1000; shared < 1003; shared++) {
			assertThat(after.findLatest(key(shared), PLANE, PREDICATE, lookup)).isTrue();
			int writer = newest(count, shared - 1000);
			assertThat(lookup.generation()).as("a key also written after the range stays with its newest writer")
					.isSameAs(generations[writer]);
			assertThat(lookup.generationIndex()).isEqualTo(writer - 7);
		}
		for (int i = from; i <= toInclusive; i++) {
			assertThat(after.findLatest(key(i), PLANE, PREDICATE, lookup)).isTrue();
			assertThat(lookup.generation()).isSameAs(merged);
			assertThat(lookup.generationIndex()).isEqualTo(from);
		}
		assertIndicesConsistent(after);
		assertThat(after.latestRowCount()).isEqualTo(before.latestRowCount());
	}

	@Test
	void aMergedRowWhoseKeyTheIndexLacksIsRejected() {
		LmdbAdjacencyDeltaGeneration[] generations = { generation(1, new long[] { key(0) }),
				generation(2, new long[] { key(1) }) };
		LmdbAdjacencyOverlaySet before = overlays(generations);
		LmdbAdjacencyDeltaGeneration merged = generation(2, new long[] { key(0), key(99) });
		assertThatThrownBy(() -> before.withReplacedRange(replacement(generations, 0, 1, merged), 0, 1,
				before.contextCatalog(), new long[0], 0L, null))
						.isInstanceOf(IllegalStateException.class);
	}

	/** Index of the newest generation among {@code count} whose shared key is {@code which} (i % 3 == which). */
	private static int newest(int count, int which) {
		for (int i = count - 1; i >= 0; i--) {
			if (i % 3 == which) {
				return i;
			}
		}
		throw new AssertionError();
	}

	private static void assertIndicesConsistent(LmdbAdjacencyOverlaySet overlays) {
		List<Long> keys = new ArrayList<>();
		overlays.forEachLatestRow((generation, generationIndex, row) -> {
			assertThat(overlays.generation(generationIndex)).as("latest-row index %d", generationIndex)
					.isSameAs(generation);
			keys.add(generation.rowKeyAt(row));
		});
		assertThat(keys).isSorted();
		assertThat(keys).doesNotHaveDuplicates();
	}

	private static long key(int i) {
		return 10_000L + i;
	}

	private static LmdbAdjacencyDeltaGeneration[] replacement(LmdbAdjacencyDeltaGeneration[] current, int from,
			int toInclusive, LmdbAdjacencyDeltaGeneration merged) {
		int removed = toInclusive - from + 1;
		LmdbAdjacencyDeltaGeneration[] replacement = new LmdbAdjacencyDeltaGeneration[current.length - removed + 1];
		System.arraycopy(current, 0, replacement, 0, from);
		replacement[from] = merged;
		System.arraycopy(current, toInclusive + 1, replacement, from + 1, current.length - toInclusive - 1);
		return replacement;
	}

	private static LmdbAdjacencyDeltaGeneration generation(long revision, long[] keys) {
		LmdbAdjacencyDeltaGeneration generation = mock(LmdbAdjacencyDeltaGeneration.class);
		when(generation.revision()).thenReturn(revision);
		when(generation.rowCount()).thenReturn((long) keys.length);
		for (int row = 0; row < keys.length; row++) {
			when(generation.rowKeyAt(row)).thenReturn(keys[row]);
			when(generation.rowPlaneAt(row)).thenReturn(PLANE);
			when(generation.rowPredicateAt(row)).thenReturn(PREDICATE);
		}
		return generation;
	}

	private static LmdbAdjacencyOverlaySet overlays(LmdbAdjacencyDeltaGeneration... generations) {
		return new LmdbAdjacencyOverlaySet(generations, mock(LmdbAdjacencyContextCatalog.class), new long[0], 0L);
	}
}
